{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.discounts import percent_discount",
    "from ledger.money import CurrencyMismatchError, Money"
  ],
  "tests": [
    {
      "name": "test_discount_exceeding_cap_is_limited",
      "intent": "the bug scenario: 25% of 200.00 with cap 30.00 returns 30.00",
      "code": "# intent: the bug scenario: 25% of 200.00 with cap 30.00 returns 30.00\ndef test_discount_exceeding_cap_is_limited():\n    assert percent_discount(Money.of(\"200.00\"), 25, cap=Money.of(\"30.00\")) == Money.of(\"30.00\")\n"
    },
    {
      "name": "test_discount_equal_to_cap_returns_cap",
      "intent": "discount exactly equal to cap is not reduced",
      "code": "# intent: discount exactly equal to cap is not reduced\ndef test_discount_equal_to_cap_returns_cap():\n    assert percent_discount(Money.of(\"120.00\"), 25, cap=Money.of(\"30.00\")) == Money.of(\"30.00\")\n"
    },
    {
      "name": "test_discount_below_cap_is_unchanged",
      "intent": "discount below cap remains unchanged",
      "code": "# intent: discount below cap remains unchanged\ndef test_discount_below_cap_is_unchanged():\n    assert percent_discount(Money.of(\"200.00\"), 10, cap=Money.of(\"30.00\")) == Money.of(\"20.00\")\n"
    },
    {
      "name": "test_zero_cap_returns_zero",
      "intent": "zero cap forces zero discount even for positive percent",
      "code": "# intent: zero cap forces zero discount even for positive percent\ndef test_zero_cap_returns_zero():\n    assert percent_discount(Money.of(\"100.00\"), 50, cap=Money.zero(\"USD\")) == Money.zero(\"USD\")\n"
    },
    {
      "name": "test_cap_currency_mismatch_raises",
      "intent": "cap in different currency raises CurrencyMismatchError",
      "code": "# intent: cap in different currency raises CurrencyMismatchError\ndef test_cap_currency_mismatch_raises():\n    with pytest.raises(CurrencyMismatchError):\n        percent_discount(Money.of(\"100.00\", \"USD\"), 10, cap=Money.of(\"5.00\", \"EUR\"))\n"
    },
    {
      "name": "test_percent_as_string_is_accepted",
      "intent": "percent can be given as a string",
      "code": "# intent: percent can be given as a string\ndef test_percent_as_string_is_accepted():\n    assert percent_discount(Money.of(\"80.00\"), \"15\", cap=Money.of(\"20.00\")) == Money.of(\"12.00\")\n"
    }
  ]
}
